mapper.select:
SELECT `id` FROM `game`
WHERE `deleted` = 1 AND `update_time` <= #{cutoff,jdbcType=TIMESTAMP}
ORDER BY `update_time`, `id`

SELECT * FROM `game`
WHERE `id` = #{id}
  AND `deleted` = 1
  AND `update_time` <= #{cutoff,jdbcType=TIMESTAMP}
FOR UPDATE


SELECT `id`, `title`, `chinese_title`, `version`, `cover`, `description`, `preview_images`, `favorite`, `deleted`, `create_time`, `update_time` FROM `game`
WHERE `user_id` = #{userId}
  AND `deleted` = #{deleted}

  AND (`title` LIKE CONCAT('%', #{title}, '%') OR `chinese_title` LIKE CONCAT('%', #{title}, '%'))

ORDER BY `id` DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM `game`
WHERE `user_id` = #{userId}
  AND `deleted` = #{deleted}

  AND (`title` LIKE CONCAT('%', #{title}, '%') OR `chinese_title` LIKE CONCAT('%', #{title}, '%'))
